steps.display:
$p = Get-Process
"process_count=$($p.Count)"
$p | Where-Object { $_.ProcessName -like '*OneDrive*' } | Sort-Object Id | ForEach-Object { "onedrive_process=$($_.ProcessName) pid=$($_.Id)" }

